// agent/pronunciation.ts
var PLATFORM_DEFAULTS = {
  deepgramKeywords: [
    ["VoiceOS", 1.5],
    ["Groq", 1.2],
    ["Cartesia", 1.2],
    ["LiveKit", 1.2],
    ["Deepgram", 1.2],
  ],
  deepgramKeyterms: ["VoiceOS"],
  ttsMap: {
    VoiceOS: "Voice O S",
    LiveKit: "Live Kit",
    Deepgram: "Deep gram",
    Groq: "Groh k",
  },
};
async function loadPronunciationConfig(agentId, supabaseUrl, supabaseKey) {
  if (!agentId) return PLATFORM_DEFAULTS;
  try {
    const db = createClient(supabaseUrl, supabaseKey, {
      auth: { persistSession: false },
    });
    const { data } = await db
      .from("agents")
      .select("widget_config")
      .eq("id", agentId)
      .single();
    const cfg = data?.widget_config;
    const p = cfg?.["pronunciation"];
    if (!p) return PLATFORM_DEFAULTS;
    return {
      deepgramKeywords: [
        ...PLATFORM_DEFAULTS.deepgramKeywords,
        ...(p.keywords ?? []),
      ],
      deepgramKeyterms: [
        ...PLATFORM_DEFAULTS.deepgramKeyterms,
        ...(p.keyterms ?? []),
      ],
      ttsMap: {
        ...PLATFORM_DEFAULTS.ttsMap,
        ...(p.tts_map ?? {}),
      },
    };
  } catch {
    return PLATFORM_DEFAULTS;
  }
}

